def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # exterior zeros by 4-neighbor flood fill, plus components of 1
    ext=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in ext: ext.add((r,c));q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in ext: ext.add((r,c));q.append((r,c))
    for r,c in list(q): pass
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in ext:
                ext.add((nr,nc));q.append((nr,nc))
    interior={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and (r,c) not in ext}
    # connected 1 components, qualify if neighboring interior cell
    seen=set(); qualifying=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=1 or (r,c) in seen: continue
        comp={(r,c)}; seen.add((r,c)); st=[(r,c)]
        while st:
          x,y=st.pop()
          for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=x+dx,y+dy
            if 0<=a<h and 0<=b<w and grid[a][b]==1 and (a,b) not in seen:
              seen.add((a,b));comp.add((a,b));st.append((a,b))
        if any((x+dx,y+dy) in interior for x,y in comp for dx,dy in ((1,0),(-1,0),(0,1),(0,-1))):
          qualifying |= comp
    for r,c in qualifying:
      for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        nr,nc=r+dr,c+dc
        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0:
          out[nr][nc]=3 if (nr,nc) in interior else 2
